class Frame:
    def __init__(self, parent=None):
        self.vars = {}  # name -> value
        self.parent = parent

def lookup(name, env):
    frame = env
    while frame is not None:
        if name in frame.vars:
            val = frame.vars[name]
            if isinstance(val, _Uninit):
                raise SchemeError(f"uninitialized variable: {name}")
            return val
        frame = frame.parent
    raise SchemeError(f"unbound variable: {name}")

def set_var(name, val, env):
    frame = env
    while frame is not None:
        if name in frame.vars:
            frame.vars[name] = val
            return
        frame = frame.parent
    raise SchemeError(f"unbound variable: {name}")
