def check_arity(formals, n):
    if isinstance(formals, Symbol):
        return  # any number
    # formals is a list (possibly dotted)
    required = []
    rest = None
    current = formals
    while isinstance(current, Pair):
        required.append(current.car)
        current = current.cdr
    if isinstance(current, Symbol):
        rest = current
    elif current is not NIL:
        raise SchemeError("malformed formals")

    if rest is None:
        if n != len(required):
            raise SchemeError("wrong number of arguments")
    else:
        if n < len(required):
            raise SchemeError("too few arguments")
```

