        frame.vars[v.name] = UNINIT

    # Evaluate inits in order
    for binding in bindings:
        v = binding.car
        init = binding.cdr.car
        val = eval_expr(init, frame, output)  # note: evaluated in the letrec frame
        frame.vars[v.name] = val

    # Evaluate body
    return eval_body_tail(body, frame, output)
