def to_python_list(lst):
    """Convert a proper Scheme list to a Python list. Raise if not proper."""
    result = []
    while isinstance(lst, Pair):
        result.append(lst.car)
        lst = lst.cdr
    if lst is not NIL:
        raise SchemeError("not a proper list")
    return result

def to_scheme_list(items):
    """Convert a Python list to a Scheme list."""
    result = NIL
    for item in reversed(items):
        result = Pair(item, result)
    return result
